fn is_happy(s: Vec<char>) -> bool {
    // A sequence must have at least 3 characters to be "happy".
    if s.len() < 3 {
        return false;
    }

    // Check every contiguous block of 3 characters for pairwise distinctness.
    for window in s.windows(3) {
        if window[0] == window[1]
            || window[0] == window[2]
            || window[1] == window[2]
        {
            return false;
        }
    }

    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_happy_sequences() {
        assert!(is_happy(vec!['a', 'b', 'c']));
        assert!(is_happy(vec!['x', 'y', 'z', 'q']));
        assert!(is_happy(vec!['1', '2', '3', '4', '5']));
    }

    #[test]
    fn test_unhappy_sequences() {
        // Too short
        assert!(!is_happy(vec![]));
        assert!(!is_happy(vec!['a']));
        assert!(!is_happy(vec!['a', 'b']));

        // Repeated in a window
        assert!(!is_happy(vec!['a', 'a', 'b']));
        assert!(!is_happy(vec!['a', 'b', 'b']));
        assert!(!is_happy(vec!['a', 'b', 'a']));
        assert!(!is_happy(vec!['x', 'y', 'z', 'y', 'w'])); // the window ["z","y","w"] is fine, but ["y","z","y"] is not
    }
}